use glintblade::{entities::{Enemy,EnemyKind,EnemyCtx,Projectile},world::{Zone,ZoneId},fx::Fx,combat::{Hit,Shape,Team}};
fn main(){let z=Zone::new(ZoneId::Bloomwild,40,40);let mut pos=[(0.0,0.0);3];let mut found=[false;3];for y in 256..276{for x in 256..276{let v=(glintblade::util::hash2(x,y,941)*3.0)as usize%3;if !found[v]{pos[v]=(x as f32,y as f32);found[v]=true;}}}
for kind in[EnemyKind::ThornImp,EnemyKind::SpittingTotem,EnemyKind::Wisp]{for skin in 0..3{let(x,y)=pos[skin];let mut e=Enemy::spawn(kind,x,y);e.awake=true;let mut fx=Fx::new(904);let mut ps=Vec::new();let mut hs=Vec::new();let mut release=None;for t in 0..3600{e.update(&mut EnemyCtx{player:(300.0,270.0),player_alive:true,zone:&z,fx:&mut fx,hits:&mut hs,projectiles:&mut ps,t});if ps.iter().any(|p|p.alive&&(kind!=EnemyKind::ThornImp||p.grav>0.0)){release=Some(t);break;}for p in&mut ps{p.update(&z,&mut fx,(300.0,270.0));}ps.retain(|p|p.alive);fx.tick();}let t=release.expect("enemy must release a live projectile");let own=ps.iter().filter(|p|p.alive).map(|p|(p.id,p.grav)).collect::<Vec<_>>();let foreign=Projectile::new(100.0,100.0,1.0,0.0,&mut fx);let foreign_id=foreign.id;let foreign_debug=format!("{:?}",foreign);ps.push(foreign);let hit=Hit::new(Shape::Circle{x:e.body.x,y:e.body.y,r:20.0},Team::Player,999,900001);assert!(e.on_hit(&hit,&mut EnemyCtx{player:(300.0,270.0),player_alive:true,zone:&z,fx:&mut fx,hits:&mut hs,projectiles:&mut ps,t}));assert!(!e.body.alive);let f=ps.iter().find(|p|p.id==foreign_id).expect("unrelated projectile retained");assert_eq!(format!("{:?}",f),foreign_debug,"foreign projectile mutated");for (id,grav) in&own{match kind{EnemyKind::ThornImp=>{if *grav>0.0 {assert!(ps.iter().all(|p|p.id!=*id),"dead imp retains lobbed seed");}else{assert!(ps.iter().any(|p|p.id==*id&&p.alive),"released level seed keeps original behavior");}},EnemyKind::SpittingTotem=>{let p=ps.iter().find(|p|p.id==*id).expect("glob remains to fizzle once");assert!(!p.alive&&p.life==0,"dead totem retains active glob");},EnemyKind::Wisp=>assert!(ps.iter().any(|p|p.id==*id&&p.alive),"ordinary released wisp bolt should retain original behavior"),_=>unreachable!()}}println!("{:?} skin={} release_tick={} owned_before={} foreign_unchanged=true expected_cancellation=true",kind,skin,t,own.len());}}
}
